[{"order":1,"type":"heading","text":"Mastering Parameterized Tests in JUnit 5"},{"order":2,"type":"paragraph","text":"Parameterized tests make it possible to run a single test method multiple times with different arguments. JUnit 5 provides robust support for parameterized tests through the junit-jupiter-params artifact. This tutorial explores the most commonly used source annotations: @ValueSource, @CsvSource, @MethodSource, and @ArgumentsProvider."},{"order":3,"type":"subheading","text":"1. Using @ValueSource"},{"order":4,"type":"paragraph","text":"The @ValueSource annotation is the simplest way to pass a single array of literal values (such as strings, ints, longs, or doubles) to a test method."},{"order":5,"type":"code","text":"import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import static org.junit.jupiter.api.Assertions.assertTrue;

public class ValueSourceTest {

    @ParameterizedTest
    @ValueSource(strings = {"apple", "banana", "cherry"})
    void testWithValidStrings(String fruit) {
        assertTrue(fruit.length() > 2);
    }
}"},{"order":6,"type":"subheading","text":"2. Using @CsvSource"},{"order":7,"type":"paragraph","text":"The @CsvSource annotation allows you to pass comma-separated values as arguments. This is ideal for testing methods that require multiple parameters of different types."},{"order":8,"type":"code","text":"import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import static org.junit.jupiter.api.Assertions.assertEquals;

public class CsvSourceTest {

    @ParameterizedTest
    @CsvSource({
        "2, 3, 5",
        "10, 15, 25",
        "-1, 1, 0"
    })
    void testAddition(int first, int second, int expectedResult) {
        assertEquals(expectedResult, first + second);
    }
}"},{"order":9,"type":"subheading","text":"3. Using @MethodSource"},{"order":10,"type":"paragraph","text":"When your test data requires complex object creation or dynamic generation, @MethodSource is the best choice. It references a factory method that returns a Stream, Collection, Iterable, or array of arguments."},{"order":11,"type":"code","text":"import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;
import java.util.stream.Stream;
import static org.junit.jupiter.api.Assertions.assertNotNull;

public class MethodSourceTest {

    @ParameterizedTest
    @MethodSource("provideStringsForTesting")
    void testWithString(String input) {
        assertNotNull(input);
    }

    static Stream<String> provideStringsForTesting() {
        return Stream.of("junit5", "parameters", "testing");
    }
}"},{"order":12,"type":"subheading","text":"4. Using @ArgumentsProvider"},{"order":13,"type":"paragraph","text":"For advanced and reusable test data providers across multiple test classes or complex logic, you can implement the ArgumentsProvider interface and reference it using @ArgumentsProvider."},{"order":14,"type":"code","text":"import org.junit.jupiter.extension.ExtensionContext;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.ArgumentsProvider;
import java.util.stream.Stream;

public class CustomArgumentsProvider implements ArgumentsProvider {

    @Override
    public Stream<? extends Arguments> provideArguments(ExtensionContext context) {
        return Stream.of(
            Arguments.of("Admin", true),
            Arguments.of("Guest", false)
        );
    }
}"},{"order":15,"type":"paragraph","text":"Here is how you apply the custom arguments provider in your test class:"},{"order":16,"type":"code","text":"import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ArgumentsProvider;
import org.junit.jupiter.params.provider.ArgumentsSource;
import static org.junit.jupiter.api.Assertions.assertEquals;

public class ArgumentsSourceTest {

    @ParameterizedTest
    @ArgumentsSource(CustomArgumentsProvider.class)
    void testUserPermissions(String role, boolean expectedAccess) {
        boolean hasAccess = role.equals("Admin");
        assertEquals(expectedAccess, hasAccess);
    }
}"},{"order":17,"type":"subheading","text":"Summary"},{"order":18,"type":"bullet_point","text":"@ValueSource: Best for single primitive or string arrays."},{"order":19,"type":"bullet_point","text":"@CsvSource: Excellent for inline tabular data with multiple columns."},{"order":20,"type":"bullet_point","text":"@MethodSource: Powerful for externalized or programmatically generated test streams."},{"order":21,"type":"bullet_point","text":"@ArgumentsProvider: Ideal for modular, reusable, and complex provider logic."}]
